let pred = $json.prediction;
let prob = Number($json.probability) || 0;

// 🎯 Status
let status = pred === 1 ? "Loyal Customer" : "Not Loyal";

// 🎯 Confidence %
let confidence = (prob * 100).toFixed(1);

// 🎯 Interpretation
let interpretation = "";

if (prob > 0.7) {
  interpretation = "High confidence prediction";
} else if (prob > 0.5) {
  interpretation = "Moderate confidence";
} else {
  interpretation = "Low confidence";
}

// 🔥 FULL NAME
let full_name = $json.full_name;
if (!full_name || full_name.trim() === "") {
  full_name = "Unknown Customer";
}

return {
  json: {
    ...$json,
    full_name,
    customer_status: status,
    confidence: confidence + "%",
    confidence_value: Number(confidence),
    interpretation
  }
};

let confidence = Number($json.confidence_value) || 0;
let status = $json.customer_status;

// 🔥 SCORE DE RISQUE (plus la confiance est basse → plus le risque est élevé)
let risk_score = 100 - confidence;

// 🔥 Ajustement selon le type client
if (status === "Not Loyal") {
  risk_score += 10;
}

// 🔥 Normalisation
risk_score = Math.max(0, Math.min(100, risk_score));

// 🎯 Niveau de risque
let risk_level = "";

if (risk_score > 70) {
  risk_level = "HIGH RISK";
} else if (risk_score > 40) {
  risk_level = "MEDIUM RISK";
} else {
  risk_level = "LOW RISK";
}

// 🚨 Urgence
let urgency = "Normal";

if (risk_score > 85) {
  urgency = "Critical";
} else if (risk_score > 70) {
  urgency = "High";
} else if (risk_score > 40) {
  urgency = "Medium";
}

// 💡 Decision (simple et propre)
let decision = "";

if (status === "Not Loyal" && risk_score > 70) {
  decision = "🚨 Immediate retention action required";
}
else if (status === "Not Loyal") {
  decision = "⚠️ Monitor customer behavior";
}
else {
  decision = "✅ Customer stable";
}

// 📊 Recommendation
let recommendation = "";

if (risk_score > 70) {
  recommendation = "Contact customer immediately";
}
else if (risk_score > 40) {
  recommendation = "Monitor engagement and send offers";
}
else {
  recommendation = "No action needed";
}

return {
  json: {
    ...$json,
    risk_score,
    risk_level,
    urgency,
    decision,
    recommendation
  }
};

// 🔥 trier par risque (du plus critique au moins critique)
items.sort((a, b) => (b.json.risk_score || 0) - (a.json.risk_score || 0));

let htmlRows = "";

for (const item of items) {
  const d = item.json;

  // 🛡 fallback valeurs
  const name = d.full_name || "Unknown";
  const status = d.customer_status || "-";
  const risk = d.risk_score || 0;
  const decision = d.decision || "-";

  // 🎨 couleur selon risque
  let color = "green";
  if (risk > 70) color = "red";
  else if (risk > 40) color = "orange";

  htmlRows += `
    <tr>
      <td>${name}</td>
      <td>${status}</td>
      <td style="color:${color}; font-weight:bold;">${risk}</td>
      <td>${decision}</td>
    </tr>
  `;
}

return [{
  json: {
    table: htmlRows,
    count: items.length
  }
}];

return items.map(item => {
  const d = item.json;

  // 🔹 Conversion rate (très important en BI)
  const visitors = d.nbr_visitors || 1;
  const reservations = d.nbr_reservations || 0;
  const conversion = reservations / visitors; // ratio réel

  // 🔹 Score équilibré (normalisé)
  const score =
    (conversion * 100) * 0.5 +                 // performance business
    (d.rating || 0) * 5 * 0.2 +                // qualité
    (d.trend_score || 0) * 0.1 -               // tendance
    (d.marketing_spend || 0) / 1000 * 0.1 -    // coût marketing réduit
    (d.entertainer_price || 0) / 1000 * 0.1;   // coût produit réduit

  // 🔹 Classification logique
  let level = "HIGH";
  if (score < 40) level = "LOW";
  else if (score < 70) level = "MEDIUM";

  return {
    json: {
      ...d,
      potential_score: score,
      potential_level: level,

      // 🔹 Texte Gemini propre
      gemini_text: `City ${d.city} belongs to cluster ${d.cluster}. 
It has ${visitors} visitors and ${reservations} reservations. 
Conversion rate: ${(conversion * 100).toFixed(2)}%. 
Potential score: ${score.toFixed(2)} (${level}).`
    }
  };
});

