const item = $json;

// 🔹 Gemini text
const rawText = item.candidates?.[0]?.content?.parts?.[0]?.text || "No insight available.";

// 🔹 Data
const city = item.city || "Unknown";
const cluster = item.cluster ?? "-";
const score = item.potential_score ?? "-";
const level = item.potential_level || "-";

// 🔹 Clean text
const insight = rawText
  .replace(/\*\*/g, '')
  .replace(/###/g, '')
  .replace(/\n/g, '<br>');

// 🔹 Dynamic color
const levelColor =
  level === "HIGH" ? "#2e7d32" :
  level === "MEDIUM" ? "#f9a825" :
  "#e53935";

// 🔹 HTML DESIGN
const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
body {
  font-family: Arial, sans-serif;
  margin: 0;
  background: #f4f6fb;
}

.container {
  max-width: 900px;
  margin: 30px auto;
  background: #fff;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 6px 18px rgba(0,0,0,0.1);
}

.header {
  background: linear-gradient(135deg, #1a237e, #3949ab);
  color: white;
  padding: 30px;
}

.header h1 {
  margin: 0;
}

.content {
  padding: 30px;
}

.grid {
  display: flex;
  gap: 15px;
  margin-bottom: 25px;
}

.card {
  flex: 1;
  background: #f8faff;
  border: 1px solid #e3e8f2;
  border-radius: 12px;
  padding: 18px;
  text-align: center;
}

.card h3 {
  margin: 0;
  font-size: 13px;
  color: #777;
}

.card .value {
  font-size: 20px;
  font-weight: bold;
  color: #1a237e;
}

.level {
  color: white;
  padding: 6px 12px;
  border-radius: 20px;
  background: ${levelColor};
  display: inline-block;
}

.insight {
  background: #fff5f5;
  border-left: 6px solid ${levelColor};
  padding: 20px;
  border-radius: 10px;
}

.footer {
  text-align: center;
  font-size: 12px;
  color: #999;
  padding: 20px;
}
</style>
</head>

<body>

<div class="container">

  <div class="header">
    <h1>BI Insight Report</h1>
    <p>${new Date().toLocaleDateString('fr-FR')}</p>
  </div>

  <div class="content">

    <div class="grid">
      <div class="card">
        <h3>City</h3>
        <div class="value">${city}</div>
      </div>

      <div class="card">
        <h3>Cluster</h3>
        <div class="value">${cluster}</div>
      </div>

      <div class="card">
        <h3>Score</h3>
        <div class="value">
          ${typeof score === "number" ? score.toFixed(2) : score}
        </div>
      </div>

      <div class="card">
        <h3>Level</h3>
        <div class="value">
          <span class="level">${level}</span>
        </div>
      </div>
    </div>

    <div class="insight">
      ${insight}
    </div>

  </div>

  <div class="footer">
    Generated automatically from BI workflow
  </div>

</div>

</body>
</html>
`;

// 🔹 Return for PDFShift
return [
  {
    json: {
      pdfshift_body: {
        source: html,
        landscape: false,
        use_print: false,
        format: "A4"
      }
    }
  }
];

const items = $input.all();

const data = items.map(item => ({
  month: item.json.month,
  nbr_reservations: parseInt(item.json.nbr_reservations)
}));

return [{ json: { data: data } }];

const result = $input.first().json;

const forecast = result.forecast_next_months;
const months = JSON.stringify(forecast.map(f => f.month));
const values = JSON.stringify(forecast.map(f => f.predicted_reservations));

const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <script src="https://cdn.jsdelivr.net/npm/chart.js"><\/script>
</head>
<body style="background:#1a1a2e; padding:20px; font-family:Arial">
  <h2 style="color:white; text-align:center">📈 Forecast Réservations - ${result.best_model}</h2>
  <h4 style="color:#aaa; text-align:center">MAPE: ${result.mape_arima}% | MAE: ${result.mae_arima}</h4>

  <table style="color:white; margin:auto; border-collapse:collapse; margin-bottom:20px">
    <tr style="background:#00d4ff; color:black">
      <th style="padding:10px 20px">Mois</th>
      <th style="padding:10px 20px">Réservations prévues</th>
    </tr>
    ${forecast.map((f, i) => `
    <tr style="background:${i % 2 === 0 ? '#16213e' : '#0f3460'}">
      <td style="padding:10px 20px; text-align:center">${f.month}</td>
      <td style="padding:10px 20px; text-align:center">${f.predicted_reservations.toLocaleString()}</td>
    </tr>`).join('')}
  </table>

  <canvas id="chart"></canvas>

  <script>
    new Chart(document.getElementById('chart'), {
      type: 'line',
      data: {
        labels: ${months},
        datasets: [{
          label: 'Réservations prévues',
          data: ${values},
          borderColor: '#00d4ff',
          backgroundColor: 'rgba(0,212,255,0.1)',
          borderWidth: 3,
          pointRadius: 6,
          fill: true,
          tension: 0.4
        }]
      },
      options: {
        plugins: { legend: { labels: { color: 'white' } } },
        scales: {
          x: { ticks: { color: 'white' }, grid: { color: '#333' } },
          y: { ticks: { color: 'white' }, grid: { color: '#333' } }
        }
      }
    });
  <\/script>
</body>
</html>`;

const encoded = Buffer.from(html).toString('base64');
const dataUrl = `data:text/html;base64,${encoded}`;

return [{
  json: {
    best_model: result.best_model,
    mape_arima: result.mape_arima,
    mae_arima: result.mae_arima,
    forecast: result.forecast_next_months,
    open_in_browser: dataUrl
  }
}];

return [
  {
    json: {
      market_count: $json.body.market_count,
      nbr_visitors: $json.body.nbr_visitors,
      nbr_reservations: $json.body.nbr_reservations,
      marketing_spend: $json.body.marketing_spend,
      rating: $json.body.rating,
      trend_score: $json.body.trend_score,
      growth_rate_pct: $json.body.growth_rate_pct,
      capacity_min: $json.body.capacity_min,
      capacity_max: $json.body.capacity_max,
      season_encoded: $json.body.season_encoded,
      event_type_encoded: $json.body.event_type_encoded,
      venue_type_encoded: $json.body.venue_type_encoded,
      city_encoded: $json.body.city_encoded
    }
  }
];

const predicted = $json.predicted_price;

// récupérer les données d'entrée depuis le Webhook
const input = $('🌐 Receive Pricing Request').first().json.body;

const market_count = Number(input.market_count || 0);
const nbr_visitors = Number(input.nbr_visitors || 0);
const nbr_reservations = Number(input.nbr_reservations || 0);
const marketing_spend = Number(input.marketing_spend || 0);
const rating = Number(input.rating || 0);
const trend_score = Number(input.trend_score || 0);
const growth_rate_pct = Number(input.growth_rate_pct || 0);

// calcul simple de demande
let demand = 'Medium';
if (nbr_reservations === 0 || nbr_visitors < 500) {
  demand = 'Low';
} else if (nbr_reservations > 200 && nbr_visitors > 3000 && rating >= 4) {
  demand = 'High';
}

// calcul simple du risque
let risk = 'Medium';
if (market_count > 50 || nbr_reservations === 0 || rating < 3) {
  risk = 'High';
} else if (market_count < 10 && nbr_reservations > 150 && rating >= 4) {
  risk = 'Low';
}

// calcul simple de confiance
let confidence = 70;

if (nbr_reservations === 0) confidence -= 25;
if (market_count > 100) confidence -= 15;
if (rating >= 4) confidence += 10;
if (trend_score > 0) confidence += 5;
if (growth_rate_pct > 0) confidence += 5;

confidence = Math.max(20, Math.min(confidence, 95));

// prix recommandé
let recommended_price = predicted;

if (demand === 'High' && risk === 'Low') {
  recommended_price = predicted * 1.05;
} else if (demand === 'Low' || risk === 'High') {
  recommended_price = predicted * 0.95;
}

// recommandation texte
let recommendation = 'Keep a balanced pricing strategy.';

if (demand === 'Low' || risk === 'High') {
  recommendation = 'Lower or maintain the price. Market conditions are weak or risky.';
} else if (demand === 'High' && risk === 'Low') {
  recommendation = 'A slight price increase is recommended due to strong demand.';
}

return [
  {
    json: {
      predicted_price: predicted,
      recommended_price: Math.round(recommended_price),
      confidence_score: Math.round(confidence),
      expected_demand: demand,
      risk_level: risk,
      strategic_recommendation: recommendation,
      scenarios: {
        conservative: Math.round(predicted * 0.90),
        balanced: Math.round(predicted),
        aggressive: Math.round(predicted * 1.05)
      }
    }
  }
];

return items.map(item => {
  const d = item.json;

  const actual = d.nbr_reservations || 0;
  const expected = d.predicted_reservations || 1;

  const deviation = actual - expected;
  const deviation_pct = (deviation / expected) * 100;

  const is_anomaly = Math.abs(deviation_pct) > 30;

  let severity = "LOW";
  if (Math.abs(deviation_pct) > 50) severity = "HIGH";
  else if (Math.abs(deviation_pct) > 30) severity = "MEDIUM";

  return {
    json: {
      ...d,
      deviation,
      deviation_pct,
      is_anomaly,
      severity
    }
  };
});

return items.map(item => {
  return {
    json: {
      city: item.json.city || "Unknown",
      cluster: item.json.cluster,
      nbr_visitors: item.json.nbr_visitors,
      nbr_reservations: item.json.nbr_reservations
    }
  };
});

return items.map(item => {
  const d = item.json;

  return {
    json: {
      anomalies_detected: d.consensus?.anomalies_detected || 0,
      anomalies_pct: d.consensus?.anomalies_pct || 0,
      anomaly_main_feature: d.feature_comparison?.[0]?.feature || "N/A",
      anomaly_impact: d.feature_comparison?.[0]?.difference_pct || 0
    }
  };
});

return items.map(item => {
  return {
    json: {
      best_model: item.json.best_model,
      mape: item.json.mape_arima,
      mae: item.json.mae_arima,
      forecast: item.json.forecast_next_months
    }
  };
});

const d = $input.first().json;

// 🔹 KPI
const visitors = d.nbr_visitors ?? d.visitors ?? 0;
const reservations = d.nbr_reservations ?? d.reservations ?? 0;

// 🔹 conversion rate
const conversion_rate = visitors > 0 ? reservations / visitors : 0;

// 🔹 classification
let performance = "";
let recommendation = "";

if ((d.anomalies_pct ?? d.anomaly_rate ?? 0) > 5 || (d.mape ?? 0) > 20) {
  performance = "Poor Performance";
  recommendation = "Improve data quality and forecasting model.";
}
else if (conversion_rate < 0.1) {
  performance = "Low Conversion";
  recommendation = "Optimize pricing and marketing strategy.";
}
else {
  performance = "Good Performance";
  recommendation = "Maintain strategy and explore upsell opportunities.";
}

// 🔹 output FINAL
return [
  {
    json: {
      // KPI
      city: d.city || "-",
      cluster: d.cluster ?? "-",

      visitors: visitors,
      reservations: reservations,
      conversion_rate: Number(conversion_rate.toFixed(3)),

      // Anomaly
      anomalies: d.anomalies_detected ?? d.anomalies ?? 0,
      anomaly_rate: d.anomalies_pct ?? d.anomaly_rate ?? 0,
      anomaly_feature: d.anomaly_main_feature ?? d.anomaly_feature ?? "N/A",

      // Forecast
      forecast: d.forecast || [],
      model: d.best_model ?? d.model ?? "N/A",
      mape: d.mape ?? 0,
      mae: d.mae ?? 0,

      // 🔥 classification
      performance_category: performance,
      recommendation: recommendation
    }
  }
];

